#!/usr/bin/env bash
# nats accounts: one per app, with its JetStream limits and one user named
# after the app (ADR 0016). Run by OpenTofu (terraform_data.nats_accounts)
# after setup.sh.
#
# stdin, one line per app (generated by proxmox/opentofu/nats.tf):
#   <app> <bcrypt hash of its password> <jetstream max_file> <jetstream max_mem>
# Only the hash reaches this host; the password lives in the encrypted
# OpenTofu state and in the app's own config. The whole file is rewritten
# each run and the server reloaded (accounts and users reload live):
# removing an app removes its account, and its streams with it, so that is
# a deliberate change, never a side effect.
set -euo pipefail

conf=/etc/nats/accounts.conf
tmp=$(mktemp /etc/nats/.accounts.XXXXXX)
trap 'rm -f "$tmp"' EXIT

n=0
{
  echo "# managed by services/nats/accounts.sh (OpenTofu) — do not edit"
  echo "accounts {"
  while read -r app hash max_file max_mem; do
    [ -n "$app" ] || continue
    [[ $app =~ ^[a-z][a-z0-9_]{0,40}$ ]] || { echo "bad app name: $app" >&2; exit 1; }
    [[ $hash =~ ^\$2[aby]\$[0-9]{2}\$[./A-Za-z0-9]{53}$ ]] || { echo "bad hash for $app" >&2; exit 1; }
    [[ $max_file =~ ^[0-9]+(MB|GB)$ && $max_mem =~ ^[0-9]+(MB|GB)$ ]] || { echo "bad limits for $app" >&2; exit 1; }
    printf '  %s {\n    jetstream { max_file: %s, max_mem: %s }\n    users = [ { user: %s, password: "%s" } ]\n  }\n' \
      "$app" "$max_file" "$max_mem" "$app" "$hash"
    n=$((n+1))
  done
  echo "}"
} > "$tmp"
[ "$n" -gt 0 ] || { echo "no accounts on stdin: keeping the current file" >&2; exit 1; }

chown root:nats "$tmp"
chmod 0640 "$tmp"
mv "$tmp" "$conf"
trap - EXIT

# Check the config before applying it; a bad file must not take the hub down.
/usr/local/bin/nats-server -c /etc/nats/nats.conf -t >/dev/null
systemctl reload nats
sleep 1
ip=$(sed -n 's/^http: \(.*\):8222$/\1/p' /etc/nats/nats.conf)
curl -fsS "http://${ip}:8222/healthz?js-enabled-only=true" >/dev/null
echo "nats accounts: ${n} app(s)"
